import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Menu, Search, ShoppingCart, 
  Star, Plus, Home, LayoutGrid, Tag, User2, MapPin, ChevronDown
} from 'lucide-react';
import { categories, products } from './data/menu';

const App = () => {
  const [activeCategory, setActiveCategory] = useState('all');
  const [vegOnly, setVegOnly] = useState(false);
  const [cart, setCart] = useState({});
  const [searchQuery, setSearchQuery] = useState('');

  const updateCart = (id, delta) => {
    setCart(prev => {
      const newQty = (prev[id] || 0) + delta;
      if (newQty <= 0) {
        const { [id]: _, ...rest } = prev;
        return rest;
      }
      return { ...prev, [id]: newQty };
    });
  };

  const mealsUnder99 = products.filter(p => p.price < 100).slice(0, 6);

  return (
    <div className="max-w-[480px] mx-auto min-h-screen bg-slate-50 pb-32 font-sans selection:bg-primary/20">
      {/* TOP HEADER AREA */}
      <div className="bg-primary pt-12 pb-6 px-5 rounded-b-[40px] shadow-lg relative overflow-hidden">
        {/* Abstract background shapes for "Orange and Blue" theme */}
        <div className="absolute top-[-20%] right-[-10%] w-64 h-64 bg-secondary/10 rounded-full blur-3xl" />

        <header className="flex items-center justify-between mb-6 relative z-10">
          <div className="flex items-center gap-3">
            <div className="bg-white p-2 rounded-full shadow-md">
              <img src="/logo.webp" alt="Logo" className="w-6 h-6 object-contain" />
            </div>
            <div className="text-white">
              <div className="flex items-center gap-1">
                <span className="font-bold text-lg">Vadodara home</span>
                <ChevronDown size={16} />
              </div>
              <p className="text-[10px] opacity-90 truncate max-w-[200px]">D-202, Second Floor, Avaneesh Hieghts...</p>
            </div>
          </div>
          <motion.button whileTap={{ scale: 0.9 }} className="text-white">
            <Menu size={28} />
          </motion.button>
        </header>

        {/* SEARCH & VEG TOGGLE */}
        <div className="flex gap-3 relative z-10">
          <div className="relative flex-1 group">
            <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
              <Search size={20} />
            </div>
            <input 
              type="text"
              placeholder="Search for 'Fries'"
              className="w-full bg-white h-12 pl-12 pr-4 rounded-2xl shadow-inner outline-none text-slate-700 font-medium placeholder:text-slate-300"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setVegOnly(!vegOnly)}
            className="bg-white rounded-2xl px-3 flex items-center gap-2 shadow-inner"
          >
            <div className="flex flex-col items-center">
              <span className="text-[8px] font-black text-slate-400 leading-none">VEG</span>
              <div className={`w-8 h-4 rounded-full relative mt-0.5 transition-colors ${vegOnly ? 'bg-green-500' : 'bg-slate-200'}`}>
                <motion.div 
                  animate={{ x: vegOnly ? 16 : 2 }}
                  className="absolute top-0.5 w-2.5 h-2.5 rounded-full bg-white shadow-sm"
                />
              </div>
            </div>
          </button>
        </div>
      </div>

      <main className="px-5 mt-6">
        {/* BANNER SECTION */}
        <section className="mb-8">
          <div className="bg-secondary rounded-[32px] overflow-hidden relative h-44 flex items-center">
            <div className="w-1/2 pl-6 relative z-10">
              <div className="bg-white text-secondary text-[10px] font-black px-2 py-0.5 rounded-full w-fit mb-2">
                BEST DEALS
              </div>
              <h2 className="text-white font-black text-2xl leading-none italic uppercase tracking-tighter">
                Lowest Prices <br /> Every Day
              </h2>
              <button className="mt-4 bg-[#FF0080] text-white text-[10px] font-black px-6 py-2.5 rounded-full shadow-lg shadow-[#FF0080]/30 active:scale-95 transition-transform">
                ORDER NOW
              </button>
            </div>
            <div className="w-1/2 h-full bg-yellow-400 rounded-l-[100px] flex items-center justify-center relative overflow-hidden">
               <div className="absolute top-4 right-4 text-right">
                 <p className="text-secondary font-black text-[10px] leading-tight uppercase">Burgers <br /> Starting at</p>
                 <p className="text-secondary font-black text-3xl">₹49</p>
               </div>
               <img 
                 src="https://images.unsplash.com/photo-1571091718767-18b5b1457add?auto=format&fit=crop&w=400&q=80" 
                 alt="Burger" 
                 className="w-4/5 h-4/5 object-contain drop-shadow-2xl rotate-12"
               />
            </div>
          </div>
        </section>

        {/* CATEGORIES */}
        <section className="mb-10">
          <div className="flex gap-6 overflow-x-auto no-scrollbar py-2">
            {categories.slice(0, 6).map((cat) => (
              <button
                key={cat.id}
                onClick={() => setActiveCategory(cat.id)}
                className="flex flex-col items-center gap-2 flex-shrink-0"
              >
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-2xl transition-all ${
                  activeCategory === cat.id 
                  ? 'bg-primary text-white shadow-lg shadow-primary/30 ring-4 ring-primary/10' 
                  : 'bg-white text-slate-700 shadow-sm'
                }`}>
                  {cat.icon}
                </div>
                <span className={`text-[10px] font-bold uppercase tracking-wide ${
                  activeCategory === cat.id ? 'text-primary' : 'text-slate-400'
                }`}>
                  {cat.name}
                </span>
              </button>
            ))}
          </div>
        </section>

        {/* MEALS UNDER 99 */}
        <section className="mb-10">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-black text-xl text-slate-800 flex items-center gap-2">
              Meals under <span className="inline-flex items-center justify-center w-10 h-10 border-2 border-slate-800 rounded-full text-sm">₹99</span>
            </h2>
            <button className="text-[#FF0080] text-xs font-bold flex items-center gap-1">
              See All <ChevronDown size={14} className="-rotate-90" />
            </button>
          </div>

          <div className="flex gap-4 overflow-x-auto no-scrollbar -mx-5 px-5 py-2">
            {mealsUnder99.map((product) => (
              <div key={product.id} className="min-w-[160px] bg-white rounded-3xl p-3 shadow-sm border border-slate-100">
                <div className="relative h-28 mb-3 rounded-2xl overflow-hidden group">
                  <img 
                    src={`https://images.unsplash.com/photo-${1500000000000 + product.id}?auto=format&fit=crop&w=400&q=80`} 
                    alt={product.name}
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                    onError={(e) => e.target.src = "https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=400&q=80"}
                  />
                  <div className="absolute top-2 left-2 bg-white/90 backdrop-blur-sm px-2 py-0.5 rounded-lg text-[8px] font-bold text-green-600 border border-green-100 flex items-center gap-1">
                    Popular
                  </div>
                  <button 
                    onClick={() => updateCart(product.id, 1)}
                    className="absolute bottom-2 right-2 bg-white text-[#FF0080] w-8 h-8 rounded-full shadow-lg flex items-center justify-center active:scale-90 transition-transform"
                  >
                    <Plus size={20} strokeWidth={3} />
                  </button>
                </div>
                <div className="flex items-center gap-1 mb-1">
                  <Star size={10} className="fill-yellow-400 text-yellow-400" />
                  <span className="text-[10px] font-bold text-slate-500">{product.rating}</span>
                </div>
                <h3 className="text-xs font-bold text-slate-800 truncate mb-0.5">{product.name}</h3>
                <p className="text-[10px] text-slate-400 truncate mb-2">Jay Mahakali Vadavap a...</p>
                <div className="flex items-center justify-between">
                   <div className="flex items-center gap-1">
                     <div className="w-3 h-3 border border-green-600 flex items-center justify-center bg-white rounded-sm">
                        <div className="w-1.5 h-1.5 bg-green-600 rounded-full" />
                     </div>
                     <span className="text-[10px] font-bold text-slate-600">₹{product.price}</span>
                   </div>
                   {product.price > 80 && (
                     <span className="text-[10px] font-black text-[#FF0080]">₹{product.price - 10}</span>
                   )}
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* POPULAR BRANDS */}
        <section className="mb-10">
           <h2 className="font-black text-xl text-slate-800 mb-4">Popular Brands</h2>
           <div className="flex gap-6 overflow-x-auto no-scrollbar py-2">
              {[
                { name: 'KFC', logo: 'https://upload.wikimedia.org/wikipedia/sco/thumb/b/bf/KFC_logo.svg/1024px-KFC_logo.svg.png' },
                { name: 'Burger King', logo: 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Burger_King_logo_%282021%29.svg/1024px-Burger_King_logo_%282021%29.svg.png' },
                { name: 'McDonald\'s', logo: 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/McDonald%27s_Golden_Arches.svg/1200px-McDonald%27s_Golden_Arches.svg.png' },
                { name: 'Domino\'s', logo: 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Domino%27s_pizza_logo.svg/1200px-Domino%27s_pizza_logo.svg.png' },
                { name: 'Pizza Hut', logo: 'https://upload.wikimedia.org/wikipedia/sco/thumb/d/d2/Pizza_Hut_logo.svg/1088px-Pizza_Hut_logo.svg.png' }
              ].map((brand, i) => (
                <div key={i} className="flex flex-col items-center gap-2">
                  <div className="w-16 h-16 rounded-full border-2 border-slate-100 p-3 bg-white shadow-sm flex items-center justify-center overflow-hidden">
                    <img src={brand.logo} alt={brand.name} className="w-full h-full object-contain" />
                  </div>
                </div>
              ))}
           </div>
        </section>
      </main>

      {/* BOTTOM NAVIGATION */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 px-6 py-4 flex items-center justify-between z-[100] safe-bottom">
        {[
          { icon: Home, label: 'Home', active: true },
          { icon: LayoutGrid, label: 'Categories' },
          { icon: Tag, label: 'Offers' },
          { icon: ShoppingCart, label: 'Cart', count: Object.values(cart).reduce((a, b) => a + b, 0) },
          { icon: User2, label: 'Account' }
        ].map((item, i) => (
          <button key={i} className="flex flex-col items-center gap-1 relative group">
            <item.icon size={22} className={item.active ? 'text-primary' : 'text-slate-400 group-hover:text-primary transition-colors'} />
            <span className={`text-[10px] font-bold ${item.active ? 'text-primary' : 'text-slate-400'}`}>{item.label}</span>
            {item.count > 0 && (
              <span className="absolute -top-1 -right-1 bg-[#FF0080] text-white text-[8px] font-black w-4 h-4 rounded-full flex items-center justify-center">
                {item.count}
              </span>
            )}
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;
